const h = $json;
const role = String(h.role || 'Other');

// Tasks every new hire gets. dueOffsetDays = days before (-) or after (+) the start date
const commonTasks = [
  { title: 'Create hotel system (PMS) login and set permissions', owner: 'IT', dueOffsetDays: -3 },
  { title: 'Issue key card and set which doors it opens', owner: 'IT', dueOffsetDays: -2 },
  { title: 'Order uniform in the confirmed size', owner: 'HR', dueOffsetDays: -5 },
  { title: 'Add to payroll and benefits', owner: 'HR', dueOffsetDays: -2 },
  { title: 'Add to shift schedule', owner: 'Manager', dueOffsetDays: -2 },
  { title: 'Assign an onboarding buddy on the same shifts', owner: 'Manager', dueOffsetDays: -2 },
  { title: 'Hotel tour and fire exit walkthrough', owner: 'HR', dueOffsetDays: 0 },
  { title: 'Health and safety training', owner: 'HR', dueOffsetDays: 0 }
];

// Extra tasks by role
const roleTasks = {
  'Front Desk Agent': [
    { title: 'Give front desk access in hotel system (check-in, guest bills, room assignments)', owner: 'IT', dueOffsetDays: -1 },
    { title: 'Set up phone extension and headset', owner: 'IT', dueOffsetDays: -1 },
    { title: 'Cash drawer and end-of-shift cash-up training', owner: 'Manager', dueOffsetDays: 1 },
    { title: 'Briefing on handling guest complaints', owner: 'Manager', dueOffsetDays: 2 }
  ],
  'Housekeeping Supervisor': [
    { title: 'Give housekeeping access in hotel system (room status)', owner: 'IT', dueOffsetDays: -1 },
    { title: 'Briefing on linen and supply stock levels', owner: 'Manager', dueOffsetDays: 1 },
    { title: 'Walkthrough of room inspection standards', owner: 'Manager', dueOffsetDays: 2 },
    { title: 'Chemical safety handling certificate', owner: 'HR', dueOffsetDays: 3 }
  ],
  'F&B Server': [
    { title: 'Set up restaurant till (POS) access and server PIN', owner: 'IT', dueOffsetDays: -1 },
    { title: 'Check food handler certificate is valid', owner: 'HR', dueOffsetDays: -1 },
    { title: 'Food allergy awareness training', owner: 'HR', dueOffsetDays: 1 },
    { title: 'Responsible alcohol serving briefing', owner: 'Manager', dueOffsetDays: 1 }
  ],
  'Duty Manager': [
    { title: 'Give manager override and room rate access in hotel system', owner: 'IT', dueOffsetDays: -1 },
    { title: 'Master key handling and sign-out rules', owner: 'Manager', dueOffsetDays: 0 },
    { title: 'Incident and emergency procedures briefing', owner: 'HR', dueOffsetDays: 1 },
    { title: 'Walkthrough of the overnight accounts check (night audit)', owner: 'Manager', dueOffsetDays: 4 }
  ],
  'Maintenance Technician': [
    { title: 'Give access to the repair request system', owner: 'IT', dueOffsetDays: -1 },
    { title: 'Issue plant room and roof access permits', owner: 'IT', dueOffsetDays: -1 },
    { title: 'Equipment lock-off safety certificate (lockout-tagout)', owner: 'HR', dueOffsetDays: 2 },
    { title: 'Procedure for escorting contractors and work permits', owner: 'Manager', dueOffsetDays: 3 }
  ]
};

const extra = roleTasks[role] || [{ title: 'Confirm role-specific system access with department head', owner: 'Manager', dueOffsetDays: -1 }];
const allTasks = commonTasks.concat(extra);

// Documents the new hire must upload
const baseDocs = ['Government ID', 'Right to work document', 'Tax form', 'Bank details', 'Signed contract'];
if (role === 'F&B Server') { baseDocs.push('Food handler certificate'); baseDocs.push('Alcohol service certificate'); }
if (role === 'Housekeeping Supervisor') { baseDocs.push('Chemical handling certificate'); }
if (role === 'Maintenance Technician') { baseDocs.push('Trade qualification certificate'); }
if (role === 'Duty Manager') { baseDocs.push('Confidentiality agreement'); }
if (String(h.employmentType) === 'Casual / on-call' || String(h.employmentType) === 'Seasonal') { baseDocs.push('Availability declaration'); }

const start = new Date(h.startDate);
const planTasks = [];
for (let i = 0; i < allTasks.length; i++) {
  const t = allTasks[i];
  const due = new Date(start.getTime() + (t.dueOffsetDays * 86400000));
  planTasks.push({
    // Unique per person + task, so resubmitting the form updates instead of duplicating
    taskKey: h.personalEmail + '::' + t.title,
    employeeEmail: h.personalEmail,
    title: t.title,
    owner: t.owner,
    dueDate: due.toISOString().slice(0, 10),
    status: 'open'
  });
}

const planDocuments = [];
for (let j = 0; j < baseDocs.length; j++) {
  planDocuments.push({
    employeeEmail: h.personalEmail,
    documentName: baseDocs[j],
    documentKey: h.personalEmail + '::' + baseDocs[j],
    status: 'outstanding'
  });
}

return {
  json: {
    fullName: h.fullName,
    personalEmail: h.personalEmail,
    workEmail: h.workEmail,
    role: role,
    department: h.department,
    property: h.property || '',
    uniformSize: h.uniformSize || '',
    managerEmail: h.managerEmail,
    location: h.location,
    startDate: h.startDate,
    employmentType: h.employmentType,
    submittedAt: h.submittedAt,
    executionId: h.executionId,
    taskCount: planTasks.length,
    documentCount: planDocuments.length,
    planTasks: planTasks,
    planDocuments: planDocuments
  }
};

