const employees = $('Find People Still Onboarding').all();
const docRows = $('Find Missing Documents').all();

// All outstanding documents, grouped by employee email.
// Fetched once per run so nobody drops out of the daily check.
const missingByEmail = {};
for (const r of docRows) {
  const d = r.json || {};
  if (!d.id || !d.employeeEmail) continue;
  const key = String(d.employeeEmail).toLowerCase();
  if (!missingByEmail[key]) missingByEmail[key] = [];
  missingByEmail[key].push(d.documentName || 'document');
}

const DAY = 86400000;
// Day 0 = start date (orientation day)
const milestoneDays = [-7, 0, 3, 7, 30];
const helpLine = 'If you have a question about policy, leave, benefits or expenses, just reply to this email and the People Team will help.';
const out = [];

for (const e of employees) {
  const emp = e.json || {};
  if (!emp.personalEmail) continue;

  const missing = missingByEmail[String(emp.personalEmail).toLowerCase()] || [];
  const hasOutstandingDocs = missing.length > 0;

  const startMs = new Date(emp.startDate).getTime();
  let dayOffset = 9999;
  if (!isNaN(startMs)) { dayOffset = Math.floor((Date.now() - startMs) / DAY); }

  const itDone = emp.itProvisioned === true || String(emp.itProvisioned).toLowerCase() === 'true';

  const base = {
    employeeRecordId: emp.id,
    personalEmail: emp.personalEmail,
    fullName: emp.fullName,
    role: emp.role,
    department: emp.department,
    managerEmail: emp.managerEmail,
    startDate: emp.startDate,
    itProvisioned: itDone,
    hasOutstandingDocs: hasOutstandingDocs,
    outstandingDocs: missing.join(', '),
    dayOffset: dayOffset,
    emailSubject: '',
    emailBody: ''
  };

  // 1) At most ONE email to the new hire per day.
  //    Milestone days win, and the missing-documents note rides along in the same email.
  const isMilestone = milestoneDays.indexOf(dayOffset) > -1;
  const docsNote = hasOutstandingDocs ? '\n\nStill needed from you: ' + missing.join(', ') + '. Please upload them using the link below, one document at a time.' : '';

  if (isMilestone) {
    let subject = '';
    let body = '';
    if (dayOffset === -7) {
      subject = 'One week to go';
      body = 'Your first day is a week away. Your accounts are being prepared, and your day-one orientation is already in your calendar.';
    } else if (dayOffset === 0) {
      subject = 'Welcome - today is your first day';
      body = 'Welcome. Your orientation session is today at 9:00. Your manager and onboarding buddy are expecting you.';
    } else if (dayOffset === 3) {
      subject = 'Resources for your first week';
      body = 'A few things worth bookmarking this week: the handbook, the benefits portal, and the expense process. If you are unsure about any policy, ask the People Team rather than guessing.';
    } else if (dayOffset === 7) {
      subject = 'How is week one going?';
      body = 'You have been here a week. Is anything still blocking you - access, equipment, or clarity on your duties? Reply to this email and we will sort it.';
    } else if (dayOffset === 30) {
      subject = 'Your 30-day check-in';
      body = 'You are a month in. We would like your honest view on how onboarding went - what helped, and what was missing. Your answer improves things for the next person.';
    }
    out.push({ json: Object.assign({}, base, {
      actionType: 'milestone_email',
      reason: 'day ' + dayOffset + ' check-in email' + (hasOutstandingDocs ? ' (with missing-documents note)' : ''),
      emailSubject: subject,
      emailBody: body + docsNote + '\n\n' + helpLine
    }), pairedItem: { item: 0 } });
  } else if (hasOutstandingDocs && dayOffset >= -7) {
    out.push({ json: Object.assign({}, base, {
      actionType: 'chase_documents',
      reason: missing.length + ' required document(s) still missing',
      emailSubject: 'Still needed before your first day',
      emailBody: 'We are still missing these onboarding documents from you: ' + missing.join(', ') + '.\n\nPlease upload them using the document upload form, one document at a time.\n\nPayroll and system access cannot be finished until these are in, so the sooner the better.'
    }), pairedItem: { item: 0 } });
  }

  // 2) IT reminder goes to Slack, not the new hire, so it runs alongside the email.
  //    Missing documents must never hold up the key card and system access chase.
  if (dayOffset >= 0 && !itDone) {
    out.push({ json: Object.assign({}, base, {
      actionType: 'chase_it',
      reason: 'employee has started but IT has not confirmed system access and key card'
    }), pairedItem: { item: 0 } });
  }

  // 3) Close out once everything is done.
  if (dayOffset >= 30 && itDone && !hasOutstandingDocs) {
    out.push({ json: Object.assign({}, base, {
      actionType: 'mark_complete',
      reason: '30 days in, all documents received, IT confirmed'
    }), pairedItem: { item: 0 } });
  }
}

return out;

