const form = $('Document Upload Form').first();
return [{
  json: Object.assign({}, form.json, { employeeEmail: String(form.json.employeeEmail || '').trim().toLowerCase() }),
  binary: form.binary
}];

// One row per document - but skip any the new hire already uploaded, so
// resubmitting the intake form never resets a received document to outstanding.
const plan = $('Generate Onboarding Plan').first().json.planDocuments || [];
const received = new Set(
  $('Find Received Documents').all()
    .map(r => String((r.json || {}).documentKey || '').toLowerCase())
    .filter(Boolean)
);
return plan
  .filter(d => !received.has(String(d.documentKey).toLowerCase()))
  .map(d => ({ json: d }));

// Airtable search returns { id, createdTime, fields: {...} }. Flatten it so
